#pragma once
template<class Check> void continuityChecks(Check check){
 using namespace ff3Assist;
 const auto before=ff3Play::physicalSerial('E');ff3Play::physical['E']=false;ff3Play::physicalEdge('E',true);ff3Play::physicalEdge('E',true);ff3Play::physicalEdge('E',false);
 check(!ff3Play::held('E')&&ff3Play::physicalSerial('E')==before+1,"a quick E press/release is retained once without counting keyboard repeats");
 ff3Play::physicalEdge('E',true);ff3Play::physicalEdge('E',false);check(ff3Play::physicalSerial('E')==before+2,"a second real press gets a new activation serial");
 auto observed=ff3Play::observedRootVelocity({0,0,0},{1,0,0},10,10.02,{0,0,0});check(std::abs(observed.x-37.5)<.001,"script-driven displacement contributes even if raw assembly velocity is zero");
 check(ff3Play::observedRootVelocity({0,0,0},{100,0,0},10,10.02,{20,0,0}).x==20,"teleports are not accepted as an extreme movement velocity");
 ff3Play::Scene s;s.valid=s.focused=s.grounded=true;s.menu=s.typing=false;s.pid=1;s.model=2;s.own=3;s.player=4;s.at=10;s.groundY=0;s.head={0,5,0};s.rootPosition={0,3.5,0};s.speed=22;s.worldGravity=196.2;s.jumpVelocity=50;s.naturalShape={2,2,3,true};s.cameraForward={0,0,-1};s.cameraRight={1,0,0};
 ff3qb::BallFlight flight;flight.id=100;flight.at=flight.lastMotion=10;flight.airborne=flight.measured=true;flight.thrower=99;flight.position={0,5,-8};flight.velocity={0,0,12};flight.gravity=28;s.balls={flight};ff3qb::BallObservation anchored{100,flight.position,{},28,true,99,true};
 check(looseActionCandidate(s,anchored,true)&&distanceDiveTarget(s,anchored,10,30,7,25).valid,"a verified moving scripted/anchored pass is eligible for dive targeting");
 auto staticScene=s;staticScene.balls.clear();check(!looseActionCandidate(staticScene,anchored,true)&&!distanceDiveTarget(staticScene,anchored,10,30,7,25).valid,"stationary anchored objects still cannot drive dive assistance");
 auto raised=anchored;raised.anchored=false;raised.radius=10;raised.position={0,10,-8};check(floorLoose(s,raised)&&diveLandingTime(s,raised,10)==0,"an enlarged floor ball is not predicted to fall through its own ground contact");
 auto pickup=anchored;pickup.position={0,.6,-8};check(looseActionCandidate(s,pickup,true)&&distanceDiveTarget(s,pickup,10,30,7,25).valid,"a verified stationary anchored football on the floor remains a legitimate pickup/dive direction target");
 ff3qb::FlightTracker flights;for(int i=0;i<=20;++i){const double t=i*.05;flights.update({{100,{40*t,20+20*t-14*t*t,0},{},28,true,99,true}},10+t,0);}check(flights.visible().size()==1&&flights.visible()[0].model.valid,"observed scripted motion produces a fitted trajectory");
 auto current=flights.visible()[0];const auto beforeFreeze=ff3qb::forecast(current,0);flights.update({{100,current.position,{},28,true,99,true}},11.5,0);check(flights.visible().size()==1,"a replication freeze above the ground retains the passive trajectory");auto retained=flights.visible()[0];const auto afterFreeze=ff3qb::forecast(retained,0);check(beforeFreeze.valid&&afterFreeze.valid&&ff3qb::length(beforeFreeze.landing-afterFreeze.landing)<.001,"render/replication time does not slide or prematurely expire a fitted landing");check(!incoming(s,retained,11.5),"retained passive flight cannot authorize input from stale motion");
 flights.update({},11.65,0);check(flights.visible().size()==1,"one short discovery gap does not erase the visible pass");flights.update({},11.9,0);check(flights.visible().empty(),"missing observations still expire without leaving a permanent ghost trajectory");
 ff3qb::FlightTracker reused;for(int i=0;i<4;++i)reused.update({{101,{double(i),5-i*.5,0},{},28,false,99,true}},10+i*.05,0);reused.update({{101,{4,.6,0},{},28,false,99,true}},10.2,0);check(reused.visible().empty(),"ground contact ends the prior flight");reused.update({{101,{20,10,0},{},28,true,99,true}},10.25,0);reused.update({{101,{22,11,0},{},28,true,99,true}},10.3,0);check(reused.visible().size()==1,"a quickly reused football can acquire a fresh flight after landing");
}
